import{_ as s,o as t,c as n,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"3. 分治 vs 贪心 vs DP: 什么是\\"最优子问题分解\\"","description":"","frontmatter":{},"headers":[],"relativePath":"_meta/decomposition-strategies.md","filePath":"_meta/decomposition-strategies.md","lastUpdated":1788475713000}'),e={name:"_meta/decomposition-strategies.md"};function l(p,a,o,d,h,r){return t(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="_3-分治-vs-贪心-vs-dp-什么是-最优子问题分解" tabindex="-1">3. 分治 vs 贪心 vs DP: 什么是&quot;最优子问题分解&quot; <a class="header-anchor" href="#_3-分治-vs-贪心-vs-dp-什么是-最优子问题分解" aria-label="Permalink to &quot;3. 分治 vs 贪心 vs DP: 什么是&quot;最优子问题分解&quot;&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>分治 / 贪心 / DP 表面上是三种范式, 仔细看它们其实是&quot;<strong>怎么把原问题分解成子问题</strong>&quot;的三个约束等级: 从几乎不设限 (分治) 到要求子问题可枚举、按序求解且共享结果 (DP). 理解三种范式的&quot;分解自由度&quot;梯度, 拿到新题就能按顺序机械地排查.</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程问题: 拿到一道新题, 先试分治、贪心还是 DP?</span></span>
<span class="line"><span>  └─► 第一问: 子问题怎么分解?</span></span>
<span class="line"><span>        └─► 子问题互不重叠, 合并即可 ──────────► 分治</span></span>
<span class="line"><span>        └─► 局部最优可证明等于全局最优 ─────────► 贪心</span></span>
<span class="line"><span>        └─► 子问题大量重叠, 需要共享解 ─────────► DP</span></span>
<span class="line"><span>  └─► 三者共用同一块地基: 最优子结构</span></span>
<span class="line"><span>        └─► 分治: 只要组合函数保持一致</span></span>
<span class="line"><span>        └─► 贪心: 再加无后效性 + 贪心选择性质</span></span>
<span class="line"><span>        └─► DP:   再加子问题空间有限、可枚举</span></span>
<span class="line"><span>  └─► 范式之间可以互相退化</span></span>
<span class="line"><span>        └─► DP 表里的冗余信息被剪掉 → 变成贪心 (LIS 的 tails 二分)</span></span></code></pre></div><h2 id="分级-从-分解自由度-看三种范式" tabindex="-1">分级: 从&quot;分解自由度&quot;看三种范式 <a class="header-anchor" href="#分级-从-分解自由度-看三种范式" aria-label="Permalink to &quot;分级: 从&quot;分解自由度&quot;看三种范式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分治: 任意分解 (递归不考虑子问题之间的依赖), 每个子问题解一次</span></span>
<span class="line"><span>贪心: 每步只看眼前局部最优, 不回退, 不组合</span></span>
<span class="line"><span>DP:   列出全部子问题, 按依赖序求解, 子问题之间共享中间结果</span></span></code></pre></div><p>三者都是&quot;分解 + 合并&quot;, 但<strong>对分解形态的约束</strong>依次更紧:</p><ul><li>分治: 对分解形态无要求, 子问题彼此独立;</li><li>贪心: 要求无后效 + 局部最优即全局最优 (贪心选择性质);</li><li>DP: 子问题之间<strong>存在重叠</strong>, 必须显式表达依赖以便 memo 化.</li></ul><h2 id="数学表达" tabindex="-1">数学表达 <a class="header-anchor" href="#数学表达" aria-label="Permalink to &quot;数学表达&quot;">​</a></h2><p>考虑原问题 <code>P(x)</code>. 三种范式都把 <code>P</code> 分解为子问题 <code>P(x_i)</code>:</p><p><strong>分治</strong>: <code>P(x) = combine(P(x1), P(x2))</code>. 子问题彼此独立.</p><p><strong>贪心</strong>: <code>P(x) = choice(x_k) + P(rest)</code>, 其中 <code>x_k</code> 是当前可证局部最优的选择. 选完直接剪掉, 不回头.</p><p><strong>DP</strong>: <code>P(x) = opt_i { P(x_i&#39;) + cost }</code>. 子问题之间是<strong>重叠</strong>的 —— 多个 <code>P(x)</code> 共享同一批 <code>P(x_i&#39;)</code>. 用一张表按拓扑序求解所有子问题, 中间结果只算一次.</p><h2 id="三种范式的共同源头" tabindex="-1">三种范式的共同源头 <a class="header-anchor" href="#三种范式的共同源头" aria-label="Permalink to &quot;三种范式的共同源头&quot;">​</a></h2><p>每种范式都假设<strong>最优子结构</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(x) 的最优解由其子问题 P(x_i) 的最优解组合而成.</span></span>
<span class="line"><span>只要组合时用的是 max / min 这类保序运算,</span></span>
<span class="line"><span>&quot;子问题取最优 ⇒ 原问题取最优&quot;就严格成立.</span></span></code></pre></div><p>进一步:</p><ul><li>分治: 不要求定序, 只要组合函数一致;</li><li>贪心: 多了 &quot;无后效&quot; + &quot;贪心选择性质&quot; 的假定;</li><li>DP: 多了 &quot;子问题集合有限、可枚举&quot; 的假定.</li></ul><p>记忆口诀: <strong>假设越紧, 适用面越窄, 但换来的复杂度上界也越漂亮</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>三种范式的完整讲解分别在 <a href="./../dsa/algorithms/divide-conquer">分治</a>、<a href="./../dsa/algorithms/greedy">贪心</a>、<a href="./../dsa/algorithms/dp">动态规划</a>; 本章只回答一个元问题——拿到新题先试哪一个、怎么判断试错了.</p></div><h2 id="同一道题三种范式的不同表现" tabindex="-1">同一道题三种范式的不同表现 <a class="header-anchor" href="#同一道题三种范式的不同表现" aria-label="Permalink to &quot;同一道题三种范式的不同表现&quot;">​</a></h2><p>例子: 最长递增子序列 (Longest Increasing Subsequence, LIS).</p><h3 id="分治解-不适用" tabindex="-1">分治解: 不适用 <a class="header-anchor" href="#分治解-不适用" aria-label="Permalink to &quot;分治解: 不适用&quot;">​</a></h3><p>LIS 几乎不可分治: 左右两半的最优解无法在不重新扫描的情况下合并. 硬写成&quot;分治 + 合并阶段交叉处理&quot;, 复杂度反而升到 O(n log² n) 或更高.</p><h3 id="dp-解-经典-o-n2" tabindex="-1">DP 解: 经典 O(n²) <a class="header-anchor" href="#dp-解-经典-o-n2" aria-label="Permalink to &quot;DP 解: 经典 O(n²)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dp[i] = max(dp[j] + 1), for j &lt; i 且 a[j] &lt; a[i]</span></span></code></pre></div><p><code>dp[i]</code> 依赖所有 <code>dp[j] (j &lt; i)</code>, 子问题重叠明显, 直接开表.</p><h3 id="贪心-二分-o-n-log-n" tabindex="-1">贪心 + 二分: O(n log n) <a class="header-anchor" href="#贪心-二分-o-n-log-n" aria-label="Permalink to &quot;贪心 + 二分: O(n log n)&quot;">​</a></h3><p>观察: 不需要保留整张 dp 表. 只需维护 <code>tails[k]</code> = 所有长度为 k+1 的递增子序列中末尾元素的最小值. 新元素比 <code>tails</code> 末端大则追加, 否则二分找到第一个大于等于它的位置替换掉.</p><p>这是一个 &quot;DP + 结构性质 + 贪心化简&quot; 的典型形式: <strong>DP 的完整表达不是必需的, 可以利用多余信息剪枝, 退化成贪心</strong>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>&quot;先写朴素 DP, 再找冗余状态退化成贪心/二分&quot; 是刷题与工程通用的升级路径; LIS 的 tails 数组之所以能二分, 是因为它本身单调——发现这类单调性往往就是从 O(n²) 到 O(n log n) 的全部距离. 相关技巧见 <a href="./../dsa/topics/searching">搜索: 二分与三分</a>.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>贪心的正确性必须证明 (交换论证 / 归纳 / 拟阵), 不能靠直觉. 反例俯拾皆是: 零钱面额 <code>[1, 3, 4]</code> 凑 6, 贪心给出 <code>4+1+1</code> 三枚, 最优却是 <code>3+3</code> 两枚. 见 <a href="./../dsa/algorithms/greedy">贪心的交换论证与适用判据</a>.</p></div><h2 id="工程师视角-怎么选范式" tabindex="-1">工程师视角: 怎么选范式 <a class="header-anchor" href="#工程师视角-怎么选范式" aria-label="Permalink to &quot;工程师视角: 怎么选范式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 子问题是否互不重叠、能直接合并?</span></span>
<span class="line"><span>   是 → 分治.</span></span>
<span class="line"><span>2. 是否有&quot;局部最优即全局最优&quot;的证明 (或拟阵结构)?</span></span>
<span class="line"><span>   有 → 贪心.</span></span>
<span class="line"><span>3. 子问题大量重叠?</span></span>
<span class="line"><span>   是 → DP.</span></span>
<span class="line"><span>4. 已写出 DP, 但某一维可以被代数压缩?</span></span>
<span class="line"><span>   是 → 剪掉那一维: 斜率优化 / 决策单调性 / 位运算压缩,</span></span>
<span class="line"><span>        往往顺势退化成&quot;DP + 二分&quot;甚至纯贪心.</span></span></code></pre></div><h2 id="多语言同构" tabindex="-1">多语言同构 <a class="header-anchor" href="#多语言同构" aria-label="Permalink to &quot;多语言同构&quot;">​</a></h2><p>DP 在各语言里写法大同小异. 但工程上<strong>记忆化 vs 显式表</strong>给语言选用带来差异:</p><table tabindex="0"><thead><tr><th>语言</th><th>记忆化写法</th><th>显式表写法</th></tr></thead><tbody><tr><td>Python</td><td><code>@lru_cache</code> 一行</td><td><code>dp[k]</code> 显式迭代</td></tr><tr><td>TS</td><td>闭包 + memo Map</td><td><code>dp[]: number[]</code> 迭代</td></tr><tr><td>Go</td><td><code>map[state]int</code></td><td>一维/二维循环 dp</td></tr><tr><td>C++</td><td><code>vector&lt;int&gt; memo</code> + 递归</td><td><code>dp[...]</code> 一维数组滚动</td></tr></tbody></table><p>Python 的装饰器是最优雅的入口, 但大输入下 Python 递归有默认 ~1000 层深度限制且函数调用极慢, 最终仍要改成&quot;拓扑序迭代&quot;. 工程上惯用的起步模式:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> functools </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lru_cache</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@lru_cache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">maxsize</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, j: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">solve(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>但上规模后必须改写成 <code>dp[i][j]</code> 循环迭代——Python 递归太慢、太深、栈可能爆.</p><h2 id="工程现实" tabindex="-1">工程现实 <a class="header-anchor" href="#工程现实" aria-label="Permalink to &quot;工程现实&quot;">​</a></h2><p>DP 类问题在大规模业务工程里出现频率不高, 真实使用场景集中在:</p><ul><li>序列对齐 (生物信息学);</li><li>Viterbi 译码 (通信、语音);</li><li>强化学习的 value iteration / Q iteration;</li><li>矩阵链乘式的循环次序优化 (BLAS 内核调度);</li><li>路径规划: DP 配合 A* 或 Dijkstra 做启发剪枝.</li></ul><p>DP 不会作为日常产品代码反复出现, 但<strong>在系统的某些&quot;模型核心&quot;位置反复出现</strong>: 你写的机器人控制、序列对齐、隐马尔可夫模型, 底层都先落到 DP.</p><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ul><li>分治 / 贪心 / DP 是&quot;分解约束&quot;严格递增的同一族范式;</li><li>同一道题不一定三种范式都能解, 但各范式之间存在明确的退化路径;</li><li>DP 是最适合充当&quot;模型核心&quot;的子问题显式表达框架;</li><li>各语言给出的语法表达差异很大, 但抽象完全同构;</li><li>LIS 的尾部二分 = &quot;DP 解出来之后用结构性单调剪枝退化成贪心&quot;的经典模式.</li></ul><h2 id="一页速查" tabindex="-1">一页速查 <a class="header-anchor" href="#一页速查" aria-label="Permalink to &quot;一页速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>分治</th><th>贪心</th><th>DP</th></tr></thead><tbody><tr><td>子问题关系</td><td>独立不重叠</td><td>每步剪枝不回头</td><td>大量重叠</td></tr><tr><td>核心前提</td><td>组合函数一致</td><td>无后效 + 贪心选择性质</td><td>最优子结构 + 可枚举</td></tr><tr><td>正确性来源</td><td>归纳</td><td>交换论证 / 拟阵 (必须证明)</td><td>最优子结构归纳</td></tr><tr><td>典型复杂度</td><td>O(n log n) 主导项</td><td>通常最低</td><td>状态数 × 转移数</td></tr><tr><td>失败信号</td><td>合并代价爆炸</td><td>找不到反例却 WA</td><td>状态空间爆炸</td></tr><tr><td>代表问题</td><td>归并排序 / FFT / 最近点对</td><td>Kruskal / Huffman / 区间调度</td><td>LCS / 背包 / 编辑距离</td></tr></tbody></table><p>下一篇: <a href="./memory-hierarchy">4. 缓存层级: 从 L1 到 HBM 到 RDMA 的同构</a></p>`,50)])])}const k=s(e,[["render",l]]);export{u as __pageData,k as default};
